/**
 * JSZip-compatible minimal ZIP builder (store method, no compression)
 * Implements the subset of JSZip API used by TemplateTester.
 */
var JSZip = (function () {
  'use strict';

  // CRC-32 table
  var crcTable = (function () {
    var t = new Uint32Array(256);
    for (var i = 0; i < 256; i++) {
      var c = i;
      for (var j = 0; j < 8; j++) {
        c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
      }
      t[i] = c;
    }
    return t;
  })();

  function crc32(buf) {
    var crc = 0xFFFFFFFF;
    for (var i = 0; i < buf.length; i++) {
      crc = crcTable[(crc ^ buf[i]) & 0xFF] ^ (crc >>> 8);
    }
    return (crc ^ 0xFFFFFFFF) >>> 0;
  }

  function strToBytes(str) {
    // UTF-8 encode
    var bytes = [];
    for (var i = 0; i < str.length; i++) {
      var c = str.charCodeAt(i);
      if (c < 0x80) {
        bytes.push(c);
      } else if (c < 0x800) {
        bytes.push(0xC0 | (c >> 6), 0x80 | (c & 0x3F));
      } else if (c < 0x10000) {
        bytes.push(0xE0 | (c >> 12), 0x80 | ((c >> 6) & 0x3F), 0x80 | (c & 0x3F));
      } else {
        bytes.push(0xF0 | (c >> 18), 0x80 | ((c >> 12) & 0x3F), 0x80 | ((c >> 6) & 0x3F), 0x80 | (c & 0x3F));
      }
    }
    return new Uint8Array(bytes);
  }

  function uint16LE(n) { return [n & 0xFF, (n >> 8) & 0xFF]; }
  function uint32LE(n) { n = n >>> 0; return [n & 0xFF, (n >> 8) & 0xFF, (n >> 16) & 0xFF, (n >> 24) & 0xFF]; }

  function concat(arrays) {
    var total = arrays.reduce(function (s, a) { return s + a.length; }, 0);
    var out = new Uint8Array(total);
    var off = 0;
    arrays.forEach(function (a) { out.set(a, off); off += a.length; });
    return out;
  }

  // DOS date/time for 2025-01-01 00:00:00
  var DOS_DATE = ((2025 - 1980) << 9) | (1 << 5) | 1; // year, month, day
  var DOS_TIME = 0;

  function JSZip() {
    this._files = [];
  }

  JSZip.prototype.file = function (name, content) {
    var data = (typeof content === 'string') ? strToBytes(content) : new Uint8Array(content);
    this._files.push({ name: name, data: data });
    return this;
  };

  JSZip.prototype.generateAsync = function (opts) {
    var files = this._files;
    var parts = [];
    var centralDir = [];
    var offset = 0;

    files.forEach(function (f) {
      var nameBytes = strToBytes(f.name);
      var crc = crc32(f.data);
      var size = f.data.length;

      // Local file header
      var lfh = new Uint8Array([
        0x50, 0x4B, 0x03, 0x04,  // signature
      ].concat(
        uint16LE(20),             // version needed: 2.0
        uint16LE(0x800),          // flags: UTF-8
        uint16LE(0),              // compression: stored
        uint16LE(DOS_TIME),
        uint16LE(DOS_DATE),
        uint32LE(crc),
        uint32LE(size),           // compressed size
        uint32LE(size),           // uncompressed size
        uint16LE(nameBytes.length),
        uint16LE(0)               // extra field length
      ));
      parts.push(lfh);
      parts.push(nameBytes);
      parts.push(f.data);

      // Central directory entry
      var cde = new Uint8Array([
        0x50, 0x4B, 0x01, 0x02,  // signature
      ].concat(
        uint16LE(20),             // version made by
        uint16LE(20),             // version needed
        uint16LE(0x800),          // flags
        uint16LE(0),              // compression: stored
        uint16LE(DOS_TIME),
        uint16LE(DOS_DATE),
        uint32LE(crc),
        uint32LE(size),
        uint32LE(size),
        uint16LE(nameBytes.length),
        uint16LE(0),              // extra field length
        uint16LE(0),              // file comment length
        uint16LE(0),              // disk number start
        uint16LE(0),              // internal attributes
        uint32LE(0),              // external attributes
        uint32LE(offset)          // relative offset of local header
      ));
      centralDir.push(cde);
      centralDir.push(nameBytes);

      offset += lfh.length + nameBytes.length + f.data.length;
    });

    var cdOffset = offset;
    var cdBytes = concat(centralDir);
    var numFiles = files.length;

    // End of central directory
    var eocd = new Uint8Array([
      0x50, 0x4B, 0x05, 0x06,  // signature
    ].concat(
      uint16LE(0),             // disk number
      uint16LE(0),             // start disk
      uint16LE(numFiles),      // entries on this disk
      uint16LE(numFiles),      // total entries
      uint32LE(cdBytes.length),
      uint32LE(cdOffset),
      uint16LE(0)              // comment length
    ));

    var blob = new Blob([concat(parts.concat([cdBytes, eocd]))], { type: 'application/zip' });
    return Promise.resolve(blob);
  };

  return JSZip;
})();
